ALTER TABLE trip_day DROP INDEX uk_trip_day, ADD INDEX idx_day_order(trip_id,day_index,is_deleted);
ALTER TABLE trip_item ADD COLUMN poi_id varchar(80) NULL, ADD COLUMN coordinate_system varchar(20) NULL;
CREATE TABLE trip_revision(id bigint unsigned PRIMARY KEY AUTO_INCREMENT,trip_id bigint unsigned NOT NULL,version bigint NOT NULL,snapshot_json longtext NOT NULL,created_by bigint unsigned NOT NULL,create_time datetime DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uk_revision(trip_id,version));
CREATE TABLE trip_share(id bigint unsigned PRIMARY KEY AUTO_INCREMENT,trip_id bigint unsigned NOT NULL,user_id bigint unsigned NOT NULL,token_hash char(64) NOT NULL,snapshot_json longtext NOT NULL,revoked tinyint NOT NULL DEFAULT 0,create_time datetime DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uk_token(token_hash));
CREATE TABLE post_interaction(user_id bigint unsigned NOT NULL,post_id bigint unsigned NOT NULL,action_type varchar(20) NOT NULL,create_time datetime DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,post_id,action_type));
CREATE TABLE post_comment(id bigint unsigned PRIMARY KEY AUTO_INCREMENT,post_id bigint unsigned NOT NULL,user_id bigint unsigned NOT NULL,content varchar(1000) NOT NULL,is_deleted tinyint NOT NULL DEFAULT 0,create_time datetime DEFAULT CURRENT_TIMESTAMP,INDEX idx_post(post_id,is_deleted,id));
CREATE TABLE ai_task(id char(36) PRIMARY KEY,user_id bigint unsigned NOT NULL,request_key varchar(80) NOT NULL,task_type varchar(20) NOT NULL,status varchar(20) NOT NULL,trip_id bigint unsigned NULL,base_version bigint NULL,input_json longtext NOT NULL,result_json longtext NULL,error_message varchar(500) NULL,create_time datetime DEFAULT CURRENT_TIMESTAMP,update_time datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uk_request(user_id,request_key));
